size_t usba_ascii_string_descr ( const uchar_t * buf , size_t buflen , char * ret_descr , size_t ret_buf_len ) { int i = 1 ; char * retstart = ret_descr ; const uchar_t * bufend = buf + buflen ; for ( buf = buf + 2 ; buf + 1 < bufend && ret_buf_len > 1 && buf [ 0 ] != 0 && buf [ 1 ] == 0 && ( i < ret_buf_len ) ; buf += 2 , i ++ ) { * ret_descr ++ = buf [ 0 ] ; } * ret_descr ++ = 0 ; return ( _PTRDIFF ( ret_descr , retstart ) ) ; } 